package main

import (
	"encoding/gob"
	"fmt"
	"os"
	"time"
)

type IdsMap map[string]int

type Query struct {
	Cmd           string
	IDs           []int
	Tags          []string
	AntiTags      []string
	Project       string
	AntiProjects  []string
	Due           time.Time
	DateFilter    string
	Priority      string
	Template      bool
	Text          string
	IgnoreContext bool
	Note          string
}

type State struct {
	Context *Query
}

func main() {
	for _, p := range os.Args[1:] {
		f, err := os.Open(p)
		if err != nil {
			fmt.Println("open err:", err)
			continue
		}
		d := gob.NewDecoder(f)
		fmt.Println("---", p)
		for i := 0; i < 5; i++ {
			var m IdsMap
			if err := d.Decode(&m); err != nil {
				fmt.Println("decode err:", err)
				break
			}
			fmt.Println("IdsMap:", m)
			var s State
			if err := d.Decode(&s); err != nil {
				fmt.Println("decode2 err:", err)
				break
			}
			fmt.Printf("State: %+v\n", s)
		}
		f.Close()
	}
}
EOF
