import re,subprocess,sys,itertools
ansi=re.compile(r'\x1b\[[0-9;]*m')
EX='/workspace/executable'
names=['ID','Priority','Tags','Due','Project','Summary']
def cell(s,W):
    if len(s) > W:
        s = s[:max(W-1,0)]
    return s.ljust(W)
def render(names,widths):
    return "  ".join(cell(n,W) for n,W in zip(names,widths))
def run(D,w):
    out=subprocess.run(['python3','/tmp/ptyrun.py','40',str(w),'HOME='+D,'--',EX,'next'],capture_output=True).stdout.decode()
    lines=[ansi.sub('',l).replace('\r','') for l in out.split('\n')]
    return lines[0] if lines else '', (lines[1] if len(lines)>1 else '')
for D in sys.argv[1:]:
    print("=== ",D)
    for w in range(18,90):
        hdr,row=run(D,w)
        cands=[]
        for widths in itertools.product(*[range(0,101) for _ in names]):
            if sum(widths)+10 != len(hdr): continue
            if render(names,widths)==hdr: cands.append(widths)
        print(f"w={w:3d} len={len(hdr):3d} hdr={hdr!r} cands={cands}")
