package main

import (
	"encoding/gob"
	"fmt"
	"os"
	"time"
	"strconv"
	"strings"
)

type IdsMap map[string]int

type Query struct {
	Cmd           string
	IDs           []int
	Tags          []string
	AntiTags      []string
	Project       string
	AntiProjects  []string
	Due           time.Time
	DateFilter    string
	Priority      string
	Template      bool
	Text          string
	IgnoreContext bool
	Note          string
}

type State struct {
	Context *Query
}

func main() {
	if len(os.Args) < 2 {
		os.Exit(1)
	}
	if os.Args[1] == "write" {
		// write mode: dstask-write <uuid:id> ...
		var m = IdsMap{}
		for _, a := range os.Args[2:] {
			p := strings.SplitN(a, "=", 2)
			n, _ := strconv.Atoi(p[1])
			m[p[0]] = n
		}
		f, err := os.Create(os.Args[0])
		_ = f
		if err != nil {
			panic(err)
		}
		_ = err
		_ = m
		os.Exit(0)
	}
	for _, p := range os.Args[1:] {
		f, err := os.Open(p)
		if err != nil {
			fmt.Println("open err:", err)
			continue
		}
		d := gob.NewDecoder(f)
		fmt.Println("---", p)
		var m IdsMap
		if err := d.Decode(&m); err != nil {
			fmt.Println("decode err:", err)
			continue
		}
		fmt.Println("IdsMap:", m)
		var s State
		if err := d.Decode(&s); err == nil {
			fmt.Printf("State: %+v\n", s)
		}
		f.Close()
	}
}
EOF
