function.arguments:
{"command": "cd /workspace && cat > yaml.go <<'GOEOF'
package main

// Minimal YAML encoder/decoder sufficient for dstask's task files.  Output is
// byte-for-byte compatible with the format produced by gopkg.in/yaml.v2 for the
// structures used by dstask.

import (
	"fmt"
	"strconv"
	"strings"
	"unicode/utf8"
)

// EncodeScalar renders a scalar value the way yaml.v2 would.
func yamlEncodeString(s string, indent int) string {
	if s == "" {
		return `""`
	}
	if strings.ContainsAny(s, "\n\r") {
		return yamlBlockScalar(s, indent)
	}
	if needsDoubleQuote(s) {
		return yamlDoubleQuote(s)
	}
	if needsSingleQuote(s) {
		return yamlSingleQuote(s)
	}
	return s
}

// needsSingleQuote reports whether the scalar must be single quoted to be
// interpreted as a string.
func needsSingleQuote(s string) bool {
	first, _ := utf8.DecodeRuneInString(s)
	switch first {
	case '!', '&', '*', '-', '?', '|', '>', '%', '@', '`', '{', '[', ']', '}', ',', '#', '\'', '"':
		return true
	case ' ':
		return true
	case ':':
		return true
	}
	if strings.HasSuffix(s, " ") {
		return true
	}
	if strings.Contains(s, ": ") || strings.Contains(s, " #") {
		return true
	}
	// leading "-" followed by a space (or only dashes)
	if strings.HasPrefix(s, "- ") {
		return true
	}
	if s == "-" {
		return true
	}
	return false
}

func needsDoubleQuote(s string) bool {
	// control characters (tab etc) and non-printable
	for _, r := range s {
		if r < 0x20 || r == 0x7f {
			return true
		}
		if r > 0x7e && r != utf8.RuneError {
