		return true
	}
	return false
}

func isBase60(s string) bool {
	i := 0
	if len(s) > 0 && (s[0] == '-' || s[0] == '+') {
		i = 1
	}
	dots := 0
	any := false
	for ; i < len(s); i++ {
		switch {
		case s[i] >= '0' && s[i] <= '9':
			any = true
		case s[i] == ':':
			dots++
		default:
			return false
		}
	}
	return any && dots >= 1
}

// ---- decoding ---------------------------------------------------------------

type yamlNode struct {
	scalar string
	list   []yamlNode
	map_   map[string]yamlNode
	isMap  bool
	isList bool
