		if i == len(lines)-1 {
			// last element: only emitted when non empty and no chomping
			if l != "" {
				b.WriteString(pad)
				b.WriteString(l)
			}
			break
		}
		if l == "" {
			b.WriteString("\n")
		} else {
			b.WriteString(pad)
			b.WriteString(l)
			b.WriteString("\n")
		}
	}
	return b.String()
}

func singleQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", "''") + "'"
}

func doubleQuote(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		switch {
		case r == '"':
			b.WriteString("\\\"")
		case r == '\\':
			b.WriteString("\\\\")
		case r == '\t':
			b.WriteString("\\t")
		case r == '\n':
			b.WriteString("\\n")
		case r == '\r':
			b.WriteString("\\r")
		case r == '\x00':
			b.WriteString("\\0")
		case r == '\x07':
			b.WriteString("\\a")
		case r == '\x08':
			b.WriteString("\\b")
		case r == '\x09':
			b.WriteString("\\t")
		case r == '\x0a':
			b.WriteString("\\n")
		case r == '\x0b':
			b.WriteString("\\v")
		case r == '\x0c':
			b.WriteString("\\f")
		case r == '\x0d':
			b.WriteString("\\r")
		case r == '\x1b':
			b.WriteString("\\e")
		case r < 0x20:
			b.WriteString(fmt.Sprintf("\\x%02X", r))
		case r == 0x7f:
			b.WriteString("\\x7F")
		case r > 0xffff:
			b.WriteString(fmt.Sprintf("\\U%08X", r))
		case r == 0xfeff || r == 0xfffe || r == 0xffff:
			b.WriteString(fmt.Sprintf("\\u%04X", r))
		case r >= 0x80:
			// printable utf-8 is emitted raw for BMP characters >= 0xa0
			if r >= 0xa0 {
				b.WriteRune(r)
			} else {
				b.WriteString(fmt.Sprintf("\\u%04X", r))
			}
		default:
			b.WriteRune(r)
		}
	}
	b.WriteByte('"')
	return b.String()
}

func needsSingle(s string) bool {
	if s == "" {
		return false
	}
	switch s[0] {
	case '!', '&', '*', '-', '?', '|', '>', '%', '@', '`', '{', '[', ']', '}', ',', '#', '\'', '"', ' ', ':':
		return true
	}
	if s[len(s)-1] == ' ' {
		return true
	}
	if strings.Contains(s, ": ") || strings.Contains(s, " #") {
		return true
	}
	if strings.HasPrefix(s, "- ") || s == "-" || strings.HasPrefix(s, "? ") {
		return true
	}
	return false
}

func needsDouble(s string) bool {
	for _, r := range s {
		if r == '\t' || r == '\r' || r < 0x20 || r == 0x7f || r > 0xffff || r == 0xfffe || r == 0xffff || r == 0xfeff {
			return true
		}
	}
	return resolvesToOther(s)
}

func resolvesToOther(s string) bool {
	switch s {
	case "", "~", "null", "Null", "NULL", "true", "True", "TRUE", "false", "False", "FALSE",
		"y", "Y", "n", "N", "yes", "Yes", "YES", "no", "No", "NO", "on", "On", "ON", "off", "Off", "OFF",
		".nan", ".NaN", ".NAN", ".inf", ".Inf", ".INF", "+.inf", "+.Inf", "+.INF", "-.inf", "-.Inf", "-.INF":
		return true
	}
	if _, err := strconv.ParseInt(s, 0, 64); err == nil {
		return true
	}
	if _, err := strconv.ParseUint(s, 0, 64); err == nil {
		return true
	}
	if _, err := strconv.ParseFloat(s, 64); err == nil {
		return true
	}
	if isBase60(s) {
		return true
	}
	if len(s) >= 8 && s[4] == '-' && s[0] >= '0' && s[0] <= '9' && s[1] >= '0' && s[1] <= '9' && s[2] >= '0' && s[2] <= '9' && s[3] >= '0' && s[3] <= '9' {
		return true
	}
	return false
}

func isBase60(s string) bool {
	i := 0
	if len(s) > 0 && (s[0] == '-' || s[0] == '+') {
		i = 1
	}
	dots := 0
	any := false
	for ; i < len(s); i++ {
		switch {
		case s[i] >= '0' && s[i] <= '9':
			any = true
		case s[i] == ':':
			dots++
		default:
			return false
		}
	}
	return any && dots >= 1
}

