	// yaml.v2 parses timestamps in several formats; RFC3339Nano is what we emit
	for _, layout := range []string{time.RFC3339Nano, time.RFC3339, "2006-01-02T15:04:05", "2006-01-02 15:04:05", "2006-01-02"} {
		if t, err := time.Parse(layout, s); err == nil {
			return t, nil
		}
	}
	return time.Time{}, fmt.Errorf("invalid time")
}

// Load reads all tasks from the repository directory.
func Load(repo string) (Tasks, error) {
	var ts Tasks
	for _, d := range taskDirs {
		dir := repo + "/" + d.dir
		entries, err := os.ReadDir(dir)
		if err != nil {
			if os.IsNotExist(err) {
				continue
			}
			return nil, err
		}
		for _, e := range entries {
			if e.IsDir() || !strings.HasSuffix(e.Name(), ".yml") {
				continue
			}
			data, err := os.ReadFile(dir + "/" + e.Name())
			if err != nil {
				return nil, err
			}
			t, err := taskFromYaml(string(data))
			if err != nil {
				return nil, fmt.Errorf("Failed to unmarshal yaml: %v\ntask: %s", err, e.Name())
			}
			if t.Status == "" {
				t.Status = d.status
			}
			t.UUID = strings.TrimSuffix(e.Name(), ".yml")
			ts = append(ts, t)
		}
	}
	return ts, nil
}

// Save writes the task into the directory matching its status.
func Save(repo string, t Task) error {
	dir := repo + "/" + dirOf(t.Status)
	if err := os.MkdirAll(dir, 0700); err != nil {
		return err
	}
	return os.WriteFile(dir+"/"+t.UUID+".yml", []byte(encodeTask(t, false)), 0600)
}

// Remove deletes the task file from the repository.
func Remove(repo string, t Task) error {
	return os.Remove(repo + "/" + dirOf(t.Status) + "/" + t.UUID + ".yml")
}

// SortTasks sorts tasks by priority then creation date.
func SortTasks(ts Tasks) Tasks {
	out := make(Tasks, len(ts))
	copy(out, ts)
	sort.SliceStable(out, func(i, j int) bool {
		if out[i].Priority != out[j].Priority {
			return priorityValue(out[i].Priority) < priorityValue(out[j].Priority)
		}
		return out[i].Created.Before(out[j].Created)
	})
	return out
}

func priorityValue(p Priority) int {
	switch p {
	case P0:
		return 0
	case P1:
		return 1
	case P2:
		return 2
	case P3:
		return 3
	}
	return 2
}
