package main

import (
	"fmt"
	"strconv"
	"strings"
)

// line is a single line of yaml with its indentation.
type yline struct {
	indent int
	text   string // content without indentation
	num    int    // 1-based line number
	raw    string
}

func splitLines(s string) []yline {
	var out []yline
	raw := strings.Split(s, "\n")
	for i, r := range raw {
		if i == len(raw)-1 && r == "" {
			continue
		}
		r = strings.TrimRight(r, "\r")
		indent := 0
		for indent < len(r) && r[indent] == ' ' {
			indent++
		}
		text := r[indent:]
		out = append(out, yline{indent: indent, text: text, num: i + 1, raw: r})
	}
	return out
}

// yamlParse parses a small subset of yaml: mappings, sequences, scalars and
// block scalars.  It returns a yamlNode tree.
func yamlParse(s string) (yamlNode, error) {
	lines := splitLines(s)
	// strip comments and blank lines except within block scalars (handled below)
	i := 0
	n, err := yamlParseNode(lines, &i, 0)
	if err != nil {
		return yamlNode{}, err
	}
	if i < len(lines) {
		l := lines[i]
		if l.text != "" && !strings.HasPrefix(l.text, "#") {
			return yamlNode{}, fmt.Errorf("line %d: unexpected content", l.num)
		}
	}
	return n, nil
}

func skipBlank(lines []yline, i *int) {
	for *i < len(lines) {
		l := lines[*i]
		if l.text == "" || strings.HasPrefix(l.text, "#") {
			*i++
			continue
		}
		break
	}
}

// yamlParseNode parses a node starting at lines[i] with the given minimum indent.
func yamlParseNode(lines []yline, i *int, minIndent int) (yamlNode, error) {
	skipBlank(lines, i)
	if *i >= len(lines) {
		return yamlNode{scalar: ""}, nil
	}
	l := lines[*i]
	if l.indent < minIndent {
		return yamlNode{scalar: ""}, nil
	}
	if strings.HasPrefix(l.text, "- ") || l.text == "-" {
		return yamlParseList(lines, i, l.indent)
	}
	return yamlParseMap(lines, i, l.indent)
}

// yamlParseList parses a sequence node.
func yamlParseList(lines []yline, i *int, indent int) (yamlNode, error) {
	node := yamlNode{isList: true}
	for *i < len(lines) {
		l := lines[*i]
		if l.indent != indent || !(strings.HasPrefix(l.text, "- ") || l.text == "-") {
			break
		}
		*i++
		rest := ""
		if strings.HasPrefix(l.text, "- ") {
			rest = l.text[2:]
		}
		if rest == "" {
			// nested structure on following lines
			child, err := yamlParseNode(lines, i, indent+1)
			if err != nil {
				return node, err
			}
			node.list = append(node.list, child)
			continue
		}
		// inline content after "- "
		if isBlockScalarHeader(rest) {
			val, err := yamlBlockScalarContent(lines, i, indent, rest)
			if err != nil {
				return node, err
			}
			node.list = append(node.list, yamlNode{scalar: val, line: l.num})
			continue
		}
		// could be "key: value" (map inside list) or a scalar
		if k, v, ok := splitKeyValue(rest); ok {
			m := yamlNode{isMap: true, map_: map[string]yamlNode{}, line: l.num}
			if v != "" {
				if isBlockScalarHeader(v) {
					val, err := yamlBlockScalarContent(lines, i, indent, v)
					if err != nil {
						return node, err
					}
					m.map_[k] = yamlNode{scalar: val, line: l.num}
				} else {
					m.map_[k] = yamlNode{scalar: unquote(v), line: l.num}
				}
			}
			// continuation lines of the same item (indented >= indent+2)
			for *i < len(lines) {
				nl := lines[*i]
				if nl.indent <= indent || nl.text == "" || strings.HasPrefix(nl.text, "#") {
					break
				}
				if strings.HasPrefix(nl.text, "- ") || nl.text == "-" {
					break
				}
				k2, v2, ok2 := splitKeyValue(nl.text)
				if !ok2 {
					break
				}
				*i++
				if v2 == "" {
					child, err := yamlParseNode(lines, i, nl.indent+1)
					if err != nil {
						return node, err
					}
					m.map_[k2] = child
				} else if isBlockScalarHeader(v2) {
					val, err := yamlBlockScalarContent(lines, i, nl.indent, v2)
					if err != nil {
						return node, err
					}
					m.map_[k2] = yamlNode{scalar: val, line: nl.num}
				} else {
					m.map_[k2] = yamlNode{scalar: unquote(v2), line: nl.num}
				}
			}
			node.list = append(node.list, m)
			continue
		}
		node.list = append(node.list, yamlNode{scalar: unquote(rest), line: l.num})
	}
	return node, nil
}

// yamlParseMap parses a mapping node.
func yamlParseMap(lines []yline, i *int, indent int) (yamlNode, error) {
	node := yamlNode{isMap: true, map_: map[string]yamlNode{}, line: lines[*i].num}
	for *i < len(lines) {
		l := lines[*i]
		if l.indent != indent {
			if l.indent < indent {
				break
			}
			return node, fmt.Errorf("line %d: unexpected indentation", l.num)
		}
		if strings.HasPrefix(l.text, "- ") || l.text == "-" {
			break
		}
		k, v, ok := splitKeyValue(l.text)
		if !ok {
			return node, fmt.Errorf("line %d: could not find expected ':'", l.num)
		}
		*i++
		if v == "" {
			child, err := yamlParseNode(lines, i, indent+1)
			if err != nil {
				return node, err
			}
			node.map_[k] = child
			continue
		}
		if isBlockScalarHeader(v) {
			val, err := yamlBlockScalarContent(lines, i, indent, v)
			if err != nil {
				return node, err
			}
			node.map_[k] = yamlNode{scalar: val, line: l.num}
			continue
		}
		node.map_[k] = yamlNode{scalar: unquote(v), line: l.num}
	}
	return node, nil
}

// splitKeyValue splits "key: value" honouring quotes in the value.
func splitKeyValue(s string) (string, string, bool) {
	for i := 0; i < len(s); i++ {
		if s[i] == ':' {
			rest := s[i+1:]
			if rest == "" || rest[0] == ' ' {
				key := s[:i]
				val := strings.TrimPrefix(rest, " ")
				return key, val, true
			}
		}
	}
	return "", "", false
}

func isBlockScalarHeader(v string) bool {
	if v == "" {
		return false
	}
	if v[0] != '|' && v[0] != '>' {
		return false
	}
	for _, c := range v[1:] {
		if !(c == '-' || c == '+' || (c >= '0' && c <= '9')) {
			return false
		}
	}
	return true
}

// yamlBlockScalarContent reads the body of a block scalar.
func yamlBlockScalarContent(lines []yline, i *int, keyIndent int, header string) (string, error) {
	chomp := byte(0)
	explicitIndent := 0
	for _, c := range header[1:] {
		if c == '-' {
			chomp = '-'
		} else if c == '+' {
			chomp = '+'
		} else if c >= '0' && c <= '9' {
			explicitIndent = explicitIndent*10 + int(c-'0')
		}
	}
	// determine the indentation of the block
	blockIndent := 0
	start := *i
	if explicitIndent > 0 {
		blockIndent = keyIndent + explicitIndent
	} else {
		for *i < len(lines) {
			l := lines[*i]
			if l.text == "" {
				*i++
				continue
			}
			blockIndent = l.indent
			break
		}
		*i = start
	}
	if blockIndent <= keyIndent {
		// empty block
		return "", nil
	}
	var b strings.Builder
	// count trailing breaks
	for *i < len(lines) {
		l := lines[*i]
		if l.text == "" {
			// blank line: part of the block if followed by more content
			b.WriteString("\n")
			*i++
			continue
		}
		if l.indent < blockIndent {
			break
		}
		if strings.HasPrefix(l.text, "#") {
			break
		}
		b.WriteString(strings.Repeat(" ", l.indent-blockIndent))
		b.WriteString(l.text)
		b.WriteString("\n")
		*i++
	}
	out := b.String()
	// apply chomping
	switch chomp {
	case '-':
		out = strings.TrimRight(out, "\n")
	case 0:
		out = strings.TrimSuffix(out, "\n") + "\n"
	}
	return out, nil
}

func unquote(s string) string {
	if len(s) >= 2 {
		if s[0] == '\'' && s[len(s)-1] == '\'' {
			return strings.ReplaceAll(s[1:len(s)-1], "''", "'")
		}
		if s[0] == '"' && s[len(s)-1] == '"' {
			return unescapeDouble(s[1 : len(s)-1])
		}
	}
	if s == "[]" || s == "{}" {
		return s
	}
	return s
}

func unescapeDouble(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c != '\\' {
			b.WriteByte(c)
			continue
		}
		if i+1 >= len(s) {
			b.WriteByte(c)
			break
		}
		i++
		switch s[i] {
		case 'n':
			b.WriteByte('\n')
		case 't':
			b.WriteByte('\t')
		case 'r':
			b.WriteByte('\r')
		case '0':
			b.WriteByte(0)
		case 'a':
			b.WriteByte(7)
		case 'b':
			b.WriteByte(8)
		case 'v':
			b.WriteByte(11)
		case 'f':
			b.WriteByte(12)
		case 'e':
			b.WriteByte(27)
		case '\\':
			b.WriteByte('\\')
		case '"':
			b.WriteByte('"')
		case 'x', 'u', 'U':
			n := 2
			if s[i] == 'u' {
				n = 4
			} else if s[i] == 'U' {
				n = 8
			}
			if i+n < len(s) {
				v, err := strconv.ParseUint(s[i+1:i+1+n], 16, 32)
				if err == nil {
					b.WriteRune(runeOf(v))
					i += n
					continue
				}
			}
			b.WriteByte('\\')
			b.WriteByte(s[i])
		default:
			b.WriteByte(s[i])
		}
	}
	return b.String()
}

