		for indent < len(r) && r[indent] == ' ' {
			indent++
		}
		text := r[indent:]
		out = append(out, yline{indent: indent, text: text, num: i + 1, raw: r})
	}
	return out
}

// yamlParse parses a small subset of yaml: mappings, sequences, scalars and
// block scalars.  It returns a yamlNode tree.
func yamlParse(s string) (yamlNode, error) {
	lines := splitLines(s)
	// strip comments and blank lines except within block scalars (handled below)
	i := 0
	n, err := yamlParseNode(lines, &i, 0)
	if err != nil {
		return yamlNode{}, err
	}
	if i < len(lines) {
		l := lines[i]
		if l.text != "" && !strings.HasPrefix(l.text, "#") {
			return yamlNode{}, fmt.Errorf("line %d: unexpected content", l.num)
		}
	}
	return n, nil
}

func skipBlank(lines []yline, i *int) {
	for *i < len(lines) {
		l := lines[*i]
		if l.text == "" || strings.HasPrefix(l.text, "#") {
			*i++
			continue
		}
		break
	}
}

// yamlParseNode parses a node starting at lines[i] with the given minimum indent.
func yamlParseNode(lines []yline, i *int, minIndent int) (yamlNode, error) {
	skipBlank(lines, i)
	if *i >= len(lines) {
		return yamlNode{scalar: ""}, nil
	}
	l := lines[*i]
	if l.indent < minIndent {
		return yamlNode{scalar: ""}, nil
	}
	if strings.HasPrefix(l.text, "- ") || l.text == "-" {
		return yamlParseList(lines, i, l.indent)
	}
	return yamlParseMap(lines, i, l.indent)
}

// yamlParseList parses a sequence node.
func yamlParseList(lines []yline, i *int, indent int) (yamlNode, error) {
	node := yamlNode{isList: true}
	for *i < len(lines) {
		l := lines[*i]
		if l.indent != indent || !(strings.HasPrefix(l.text, "- ") || l.text == "-") {
			break
		}
		*i++
		rest := ""
		if strings.HasPrefix(l.text, "- ") {
			rest = l.text[2:]
		}
		if rest == "" {
			// nested structure on following lines
			child, err := yamlParseNode(lines, i, indent+1)
			if err != nil {
				return node, err
			}
			node.list = append(node.list, child)
			continue
		}
