		if isBlockScalarHeader(rest) {
			val, err := yamlBlockScalarContent(lines, i, indent, rest)
			if err != nil {
				return node, err
			}
			node.list = append(node.list, yamlNode{scalar: val, line: l.num})
			continue
		}
