// splitKeyValue splits "key: value" honouring quotes in the value.
func splitKeyValue(s string) (string, string, bool) {
	for i := 0; i < len(s); i++ {
		if s[i] == ':' {
			rest := s[i+1:]
			if rest == "" || rest[0] == ' ' {
				key := s[:i]
				val := strings.TrimPrefix(rest, " ")
				return key, val, true
			}
		}
	}
	return "", "", false
}

func isBlockScalarHeader(v string) bool {
	if v == "" {
		return false
	}
	if v[0] != '|' && v[0] != '>' {
		return false
	}
	for _, c := range v[1:] {
		if !(c == '-' || c == '+' || (c >= '0' && c <= '9')) {
			return false
		}
	}
	return true
}

// yamlBlockScalarContent reads the body of a block scalar.
func yamlBlockScalarContent(lines []yline, i *int, keyIndent int, header string) (string, error) {
	chomp := byte(0)
	explicitIndent := 0
	for _, c := range header[1:] {
		if c == '-' {
			chomp = '-'
		} else if c == '+' {
			chomp = '+'
		} else if c >= '0' && c <= '9' {
			explicitIndent = explicitIndent*10 + int(c-'0')
		}
	}
	// determine the indentation of the block
	blockIndent := 0
	start := *i
	if explicitIndent > 0 {
		blockIndent = keyIndent + explicitIndent
	} else {
		for *i < len(lines) {
			l := lines[*i]
			if l.text == "" {
				*i++
				continue
			}
			blockIndent = l.indent
			break
		}
		*i = start
	}
	if blockIndent <= keyIndent {
		// empty block
		return "", nil
	}
	var b strings.Builder
	// count trailing breaks
	for *i < len(lines) {
		l := lines[*i]
		if l.text == "" {
			// blank line: part of the block if followed by more content
			b.WriteString("\n")
			*i++
			continue
		}
		if l.indent < blockIndent {
			break
		}
		if strings.HasPrefix(l.text, "#") {
			break
		}
		b.WriteString(strings.Repeat(" ", l.indent-blockIndent))
		b.WriteString(l.text)
		b.WriteString("\n")
		*i++
	}
	out := b.String()
	// apply chomping
	switch chomp {
	case '-':
		out = strings.TrimRight(out, "\n")
	case 0:
		out = strings.TrimSuffix(out, "\n") + "\n"
	}
	return out, nil
}

func unquote(s string) string {
	if len(s) >= 2 {
		if s[0] == '\'' && s[len(s)-1] == '\'' {
			return strings.ReplaceAll(s[1:len(s)-1], "''", "'")
		}
		if s[0] == '"' && s[len(s)-1] == '"' {
			return unescapeDouble(s[1 : len(s)-1])
		}
	}
	if s == "[]" || s == "{}" {
		return s
	}
	return s
}

func unescapeDouble(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c != '\\' {
			b.WriteByte(c)
			continue
		}
		if i+1 >= len(s) {
			b.WriteByte(c)
			break
		}
		i++
		switch s[i] {
		case 'n':
			b.WriteByte('\n')
		case 't':
			b.WriteByte('\t')
		case 'r':
			b.WriteByte('\r')
		case '0':
			b.WriteByte(0)
		case 'a':
			b.WriteByte(7)
		case 'b':
			b.WriteByte(8)
		case 'v':
			b.WriteByte(11)
		case 'f':
			b.WriteByte(12)
		case 'e':
			b.WriteByte(27)
		case '\\':
			b.WriteByte('\\')
		case '"':
			b.WriteByte('"')
		case 'x', 'u', 'U':
			n := 2
			if s[i] == 'u' {
				n = 4
			} else if s[i] == 'U' {
				n = 8
			}
			if i+n < len(s) {
				v, err := strconv.ParseUint(s[i+1:i+1+n], 16, 32)
				if err == nil {
					b.WriteRune(runeOf(v))
					i += n
					continue
				}
			}
			b.WriteByte('\\')
			b.WriteByte(s[i])
		default:
			b.WriteByte(s[i])
		}
	}
	return b.String()
}

func runeOf(v uint64) rune {
	if v > 0x10ffff {
		return rune(0xfffd)
	}
	return rune(v)
}
