{"command": "cd /workspace && cat > util.go <<'GOEOF'
package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

// ANSI colour helpers, matching dstask's palette.
const (
	colourReset = "\x1b[0m"
)

// Colour codes used in the table output.
const (
	colourCritical = 160
	colourHigh     = 166
	colourNormal   = 250
	colourLow      = 245
	colourActive   = 233
	colourPaused   = 250
	bgNormal       = 233
	bgStriped      = 232
	bgActive       = 250
	bgPaused       = 236
)

func colourDim(s string) string { return "\x1b[38;5;245m" + s + "\x1b[0m" }
func colourRed(s string) string { return "\x1b[31m" + s + "\x1b[0m" }

func printDim(s string) { fmt.Print("\x1b[38;5;245m" + s + "\n" + "\x1b[0m") }

func errorf(format string, a ...interface{}) {
	fmt.Fprintln(os.Stderr, colourRed(fmt.Sprintf(format, a...)))
}

func fail(format string, a ...interface{}) {
	errorf(format, a...)
	os.Exit(1)
}

// ConfirmOrAbort asks the user a yes/no question, aborting on anything but "y".
func ConfirmOrAbort(question string, args ...interface{}) bool {
	fmt.Printf(question+" [y/n] ", args...)
	reader := bufio.NewReader(os.Stdin)
	line, err := reader.ReadString('\n')
	if err != nil {
		panic(err)
	}
	line = strings.TrimSpace(line)
	if line != "y" && line != "Y" {
		errorf("Aborted.")
		return false
	}
	return true
}

// Confirm asks a yes/no question and returns the answer.
func Confirm(question string, args ...interface{}) bool {
	fmt.Printf(question+" [y/n] ", args...)
	reader := bufio.NewReader(os.Stdin)
	line, err := reader.ReadString('\n')
	if err != nil {
		panic(err)
	}
	line = strings.TrimSpace(line)
	return line == "y" || line == "Y"
}

// isTTY reports whether the file descriptor is attached to a terminal.
func isTTY(f *os.File) bool {
	st, err := f.Stat()
	if err != nil {
		return false
	}
	return (st.Mode() & os.ModeCharDevice) != 0
}

// slug converts a task summary into a file-system friendly string.
func slug(s string) string {
	var b strings.Builder
	for _, r := range s {
		switch {
		case r >= 'a' && r <= 'z', r >= 'A' && r <= 'Z', r >= '0' && r <= '9':
			b.WriteRune(r)
		case r == ' ':
			b.WriteByte('-')
		}
	}
	return b.String()
}
GOEOF
gofmt -l util.go; echo ok"}

