{"command": "cd /workspace && cat > table.go <<'GOEOF'
package main

import (
	"fmt"
	"strings"
	"time"
)

// Column descriptions for the task list table.
type column struct {
	name  string
	width int
}

// Table renders a table in the style dstask uses.
type Table struct {
	headers []string
	rows    [][]string
	// extra content printed below the table
	extra []string
}

func NewTable(headers []string) *Table {
	return &Table{headers: headers}
}

func (t *Table) AddRow(cells []string) {
	t.rows = append(t.rows, cells)
}

func (t *Table) AddExtra(s string) {
	t.extra = append(t.extra, s)
}

// computeWidths returns the width of each column.  Columns start at a width of
// one and the available space is distributed one character at a time,
// right-to-left, skipping columns that have reached their natural width.  If
// the terminal is too narrow, columns are shrunk left-to-right (the same cycle
// in reverse).
func (t *Table) computeWidths(termWidth int) []int {
	n := len(t.headers)
	natural := make([]int, n)
	for i, h := range t.headers {
		natural[i] = len(h)
	}
	for _, row := range t.rows {
		for i, c := range row {
			if i < n && len(c) > natural[i] {
				natural[i] = len(c)
			}
		}
	}
	widths := make([]int, n)
	total := 0
	for i := range widths {
		widths[i] = 1
		total++
	}
	target := termWidth - 2*(n-1)
	if target < n {
		target = n
	}
	// grow
	loops := 0
	for total < target {
		grown := false
		for i := n - 1; i >= 0; i-- {
			if widths[i] < natural[i] {
				widths[i]++
				total++
				grown = true
				break
			}
		}
		if !grown {
			break
		}
		loops++
		if loops > 1<<20 {
			break
		}
	}
	// shrink
	for total > target {
		grown := false
		for i := 0; i < n; i++ {
			if widths[i] > 1 {
				widths[i]--
				total--
				grown = true
				break
			}
		}
		if !grown {
			break
		}
	}
	return widths
}

func cell(s string, w int) string {
	if len(s) > w {
		if w < 1 {
			return ""
