{"command": "cd /workspace && cat > git.go <<'GOEOF'
package main

import (
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

// Git holds the state of the repository dstask is operating on.
type Git struct {
	repo string
}

// NewGit looks up the git binary and returns a handle for the repository.
func NewGit(repo string) (*Git, error) {
	p, err := exec.LookPath("git")
	if err != nil {
		return nil, errors.New("git required, please install")
	}
	return &Git{repo: repo}, nil
}

// RepoDir returns the path of the dstask repository.
func RepoDir() string {
	if v := os.Getenv("DSTASK_GIT_REPO"); v != "" {
		return v
	}
	home, err := os.UserHomeDir()
	if err != nil {
		home = os.Getenv("HOME")
	}
	return filepath.Join(home, ".dstask")
}

// Run executes a git command in the repository, returning its stdout.
func (g *Git) Run(args ...string) (string, error) {
	cmd := exec.Command(g.bin, append([]string{"-C", g.repo}, args...)...)
	out, err := cmd.Output()
	return string(out), err
}

var gitBinary string

func (g *Git) bin() string { return gitBinary }

// RunInherited runs a git command with the given output writers.
func (g *Git) RunInherited(args ...string) (string, error) {
	cmd := exec.Command(g.bin(), append([]string{"-C", g.repo}, args...)...)
	var out strings.Builder
	cmd.Stdout = &out
	cmd.Stderr = os.Stderr
	err := cmd.Run()
	return out.String(), err
}

// InitRepo initialises a brand new dstask repository.
func InitRepo(repo string) error {
	if err := os.MkdirAll(repo, 0700); err != nil {
		return err
	}
	cmd := exec.Command(gitBinary, "-C", repo, "init")
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		return err
	}
	for _, d := range taskDirs {
		if err := os.MkdirAll(filepath.Join(repo, d.dir), 0700); err != nil {
			return err
		}
	}
	fmt.Printf("\nAdd a remote repository with:\n\n\tdstask git remote add origin <repo>\n\n")
	return nil
}

// HasObjects reports whether the repository's object database contains
// anything.  This is used to decide whether the diff-index check is needed.
func HasObjects(repo string) bool {
	entries, err := os.ReadDir(filepath.Join(repo, ".git", "objects"))
	if err != nil {
		return false
	}
	return len(entries) > 2
}

// Commit stages all changes and commits them with the given message.
// Returns ErrNoChanges when there is nothing to commit.
func (g *Git) Commit(msg string) error {
	if err := g.stage(); err != nil {
		return err
	}
	if HasObjects(g.repo) {
		if err := g.diffIndexQuiet(); err == nil {
			return ErrNoChanges
		}
	}
	fmt.Print("\x1b[38;5;245m")
	cmd := exec.Command(g.bin(), "-C", g.repo, "commit", "--no-gpg-sign", "-m", msg)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	err := cmd.Run()
	if err != nil {
		return fmt.Errorf("error: failed to commit changes: %v", err)
	}
	fmt.Print("\x1b[0m")
	return nil
}

func (g *Git) stage() error {
	cmd := exec.Command(g.bin(), "-C", g.repo, "add", ".")
	cmd.Stdout = nil
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		return fmt.Errorf("error: failed to stage changes: %v", err)
	}
	return nil
}

func (g *Git) diffIndexQuiet() error {
	cmd := exec.Command(g.bin(), "-C", g.repo, "diff-index", "--quiet", "HEAD", "--")
	cmd.Stdout = nil
	cmd.Stderr = os.Stderr
	return cmd.Run()
}

// ErrNoChanges is returned when a commit would be empty.
var ErrNoChanges = errors.New("no changes")

// Sync pulls then pushes to the remote.
func (g *Git) Sync() error {
	if out, err := g.RunInherited("pull", "--ff", "--no-rebase", "--no-edit", "--commit"); err != nil {
		_ = out
		errorf("Failed to run git cmd.")
		os.Exit(1)
	}
	if _, err := g.RunInherited("push"); err != nil {
		errorf("Failed to run git cmd.")
		os.Exit(1)
	}
	return nil
}

// Undo reverts the last n commits.
func (g *Git) Undo(n int) error {
	_, err := g.RunInherited("revert", "--no-gpg-sign", "--no-edit", fmt.Sprintf("HEAD~%d..", n))
	if err != nil {
		errorf("Failed to run git cmd.")
		return err
	}
	return nil
}

// Passthrough runs an arbitrary git command.
func (g *Git) Passthrough(args ...string) error {
	cmd := exec.Command(g.bin(), append([]string{"-C", g.repo}, args...)...)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		errorf("Failed to run git cmd.")
		return err
	}
	return nil
}
GOEOF
gofmt -l git.go 2>&1 | head -3"}

