	IDs           []int
	Tags          []string
	AntiTags      []string
	Project       string
	AntiProjects  []string
	Due           time.Time
	DateFilter    string
	Priority      string
	Template      bool
	Text          string
	IgnoreContext bool
	Note          string
}

// State is the persisted state of dstask (currently just the context).
type State struct {
	Context *Query
}

func idsPath(repo string) string   { return filepath.Join(repo, ".git", "dstask", "ids.bin") }
func statePath(repo string) string { return filepath.Join(repo, ".git", "dstask", "state.bin") }

// LoadIds reads the ids file, returning an empty map when missing.
func LoadIds(repo string) IdsMap {
	f, err := os.Open(idsPath(repo))
	if err != nil {
		return IdsMap{}
	}
	defer f.Close()
	var m IdsMap
	if err := gob.NewDecoder(f).Decode(&m); err != nil {
		return IdsMap{}
	}
	return m
}

// SaveIds writes the ids file.
func SaveIds(repo string, m IdsMap) error {
	if err := os.MkdirAll(filepath.Join(repo, ".git", "dstask"), 0755); err != nil {
		return err
	}
	f, err := os.Create(idsPath(repo))
	if err != nil {
		return err
	}
	defer f.Close()
	return gob.NewEncoder(f).Encode(m)
}

// LoadState reads the state file, returning nil when missing.
func LoadState(repo string) *State {
	f, err := os.Open(statePath(repo))
	if err != nil {
		return nil
	}
	defer f.Close()
	var s State
	if err := gob.NewDecoder(f).Decode(&s); err != nil {
		return nil
	}
	return &s
}

// SaveState writes the state file.
func SaveState(repo string, s *State) error {
	if err := os.MkdirAll(filepath.Join(repo, ".git", "dstask"), 0755); err != nil {
		return err
	}
	f, err := os.Create(statePath(repo))
	if err != nil {
		return err
	}
	defer f.Close()
	return gob.NewEncoder(f).Encode(s)
}

// AssignIds gives every non-resolved task that has no id the next free id.
func AssignIds(ts Tasks, m IdsMap) IdsMap {
	if m == nil {
		m = IdsMap{}
	}
	used := map[int]bool{}
	for _, t := range ts {
		if t.Status == Resolved {
			continue
		}
		if id, ok := m[t.UUID]; ok {
			used[id] = true
		}
	}
	for _, t := range ts {
		if t.Status == Resolved {
			continue
		}
		if _, ok := m[t.UUID]; ok {
			continue
		}
		for i := 1; ; i++ {
			if !used[i] {
				m[t.UUID] = i
				used[i] = true
				break
			}
		}
	}
	return m
}

// WithIds sets the in-memory id of each task.
func (ts Tasks) WithIds(m IdsMap) Tasks {
	for i := range ts {
		if t, ok := m[ts[i].UUID]; ok {
			ts[i].id = t
		} else {
			ts[i].id = 0
		}
	}
	return ts
}
