{"command": "cd /workspace && cat > query.go <<'GOEOF'
package main

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
	"time"
)

// ErrNoIDs is returned when a command requires ids but none were given.
var ErrNoIDs = errors.New("no ID(s) specified")

// ErrOperators is returned when operators are combined with task ids.
var ErrOperators = errors.New("operators not valid when addressing task by ID")

// cmdAliases maps aliases to canonical commands.
var cmdAliases = map[string]string{
	"rm":         "remove",
	"resolve":    "done",
	"notes":      "note",
	"show-next":  "next",
}

// commands is the canonical list of commands, in the order used for help.
var commands = []string{
	"next", "add", "template", "log", "start", "note", "stop", "done", "context",
	"modify", "edit", "undo", "sync", "open", "git", "remove", "show-projects",
	"show-tags", "show-active", "show-paused", "show-open", "show-resolved",
	"show-templates", "show-unorganised", "bash-completion", "fish-completion",
	"zsh-completion", "help", "version",
}

// allCommandWords is the list used for completion; aliases included.
var allCommandWords = []string{
	"next", "add", "rm", "remove", "template", "log", "start", "note", "notes",
	"stop", "done", "resolve", "context", "modify", "edit", "undo", "sync",
	"open", "git", "show-next", "show-projects", "show-tags", "show-active",
	"show-paused", "show-open", "show-resolved", "show-templates",
	"show-unorganised", "bash-completion", "fish-completion", "zsh-completion",
	"help", "version",
}

// isCommand reports whether s names a command.
func isCommand(s string) bool {
	for _, c := range allCommandWords {
		if c == s {
			return true
		}
	}
	return false
}

// ParseQuery parses command line arguments into a Query.
func ParseQuery(args []string, context *Query) (*Query, error) {
	q := &Query{}
	if context != nil {
		q.Tags = append([]string{}, context.Tags...)
		q.AntiTags = append([]string{}, context.AntiTags...)
		q.Project = context.Project
		q.AntiProjects = append([]string{}, context.AntiProjects...)
		q.Priority = context.Priority
	}
	ignore := false
	note := false
	for _, a := range args {
		if a == "--" {
			ignore = true
			q.IgnoreContext = true
			continue
		}
		if a == "/" {
			note = true
			continue
		}
		if note {
			q.Note = strings.TrimSpace(q.Note + " " + a)
			continue
		}
		if q.Cmd == "" && isCommand(a) {
			q.Cmd = a
			if c, ok := cmdAliases[q.Cmd]; ok {
				q.Cmd = c
			}
			continue
		}
		if !ignore {
			if n, err := strconv.Atoi(a); err == nil {
				q.IDs = append(q.IDs, n)
				continue
			}
		}
		if strings.HasPrefix(a, "+") && len(a) > 1 {
			q.Tags = append(q.Tags, strings.ToLower(a[1:]))
			continue
		}
		if strings.HasPrefix(a, "-") {
			rest := a[1:]
			if strings.HasPrefix(rest, "project:") {
				q.AntiProjects = append(q.AntiProjects, rest[len("project:"):])
				continue
			}
			if rest != "" {
				q.AntiTags = append(q.AntiTags, strings.ToLower(rest))
				continue
			}
		}
		if strings.HasPrefix(a, "project:") {
			q.Project = a[len("project:"):]
			continue
		}
		if strings.HasPrefix(a, "template:") {
			q.Template = true
			tid := a[len("template:"):]
			if tid != "" {
				if n, err := strconv.Atoi(tid); err == nil {
					q.IDs = append(q.IDs, n)
				}
			}
			continue
		}
		if strings.HasPrefix(a, "due:") {
			d, err := parseDueDate(strings.ToLower(a[len("due:"):]))
			if err != nil {
				return nil, err
			}
			q.Due = d
			q.DateFilter = strings.ToLower(a[len("due:"):])
			continue
		}
		if priorityRe.MatchString(a) {
			q.Priority = a
