func weekdayIndex(s string) (int, bool) {
	names := []string{"sun", "mon", "tue", "wed", "thu", "fri", "sat",
		"sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"}
	for i, n := range names {
		if i < 7 {
			if n == s {
				return i, true
			}
		}
	}
	for i := 7; i < len(names); i++ {
		if names[i] == s {
			return i - 7, true
		}
	}
	return 0, false
}
