	}
	if _, err := g.RunInherited("push"); err != nil {
		errorf("Failed to run git cmd.")
		os.Exit(1)
	}
	return nil
}

// Undo reverts the last n commits.
func (g *Git) Undo(n int) error {
	_, err := g.RunInherited("revert", "--no-gpg-sign", "--no-edit", fmt.Sprintf("HEAD~%d..", n))
	if err != nil {
		errorf("Failed to run git cmd.")
		return err
	}
	return nil
}

// Passthrough runs an arbitrary git command.
func (g *Git) Passthrough(args ...string) error {
	cmd := exec.Command(g.bin, append([]string{"-C", g.repo}, args...)...)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		errorf("Failed to run git cmd.")
		return err
	}
	return nil
}
