		if x == v {
			return true
		}
	}
	return false
}

func taskString(t Task) string {
	return fmt.Sprintf("%d: %s", t.id, t.Summary)
}

func appendNote(t *Task, text string) {
	if text == "" {
		return
	}
	if t.Notes == "" {
		t.Notes = text
	} else {
		t.Notes = t.Notes + "\n" + text
	}
}

func appendNotePadded(t *Task, text string) {
	if text == "" {
		return
	}
	t.Notes = t.Notes + "\n" + text
}

// applyOperators mutates a task according to the operators in q.
func applyOperators(t *Task, q *Query) bool {
	changed := false
	for _, tag := range q.Tags {
		if !t.HasTag(tag) {
			t.Tags = append(t.Tags, tag)
			sortStrings(t.Tags)
			changed = true
		}
	}
	for _, tag := range q.AntiTags {
		if t.HasTag(tag) {
			t.Tags = removeString(t.Tags, tag)
			changed = true
		}
	}
	if q.Project != "" && t.Project != q.Project {
		t.Project = q.Project
		changed = true
	}
	for _, p := range q.AntiProjects {
		if t.Project == p {
			t.Project = ""
			changed = true
		}
	}
	if q.Priority != "" && string(t.Priority) != q.Priority {
		t.Priority = Priority(q.Priority)
		changed = true
	}
	return changed
}

// Commit stages all changes and commits them with the given message.  When
// nothing has changed, "No changes detected" is printed instead.
func (g *Git) Commit(msg string) {
	fmt.Print("\x1b[38;5;245m")
	cmd := exec.Command(g.bin, "-C", g.repo, "add", ".")
	cmd.Stdout = nil
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		errorf("error: failed to add changes to repo: %v", err)
		os.Exit(1)
	}
	if HasObjects(g.repo) {
		c := exec.Command(g.bin, "-C", g.repo, "diff-index", "--quiet", "HEAD", "--")
		c.Stdout = nil
		c.Stderr = os.Stderr
		if err := c.Run(); err == nil {
			fmt.Print("No changes detected\n")
			fmt.Print("\x1b[0m")
			return
		}
	}
	c := exec.Command(g.bin, "-C", g.repo, "commit", "--no-gpg-sign", "-m", msg)
	c.Stdout = os.Stdout
	c.Stderr = os.Stderr
	if err := c.Run(); err != nil {
		errorf("error: failed to commit changes: %v", err)
		os.Exit(1)
	}
	fmt.Print("\x1b[0m")
}

// ---------- task creation ----------------------------------------------------

func newTaskFromQuery(q *Query) Task {
	t := Task{
		UUID:     NewUUID(),
		Status:   Pending,
		Summary:  q.Text,
		Priority: P2,
		Created:  time.Now().UTC(),
	}
	for _, tag := range q.Tags {
		t.Tags = append(t.Tags, tag)
	}
	t.Project = q.Project
	if q.Priority != "" {
		t.Priority = Priority(q.Priority)
	}
	if !q.Due.IsZero() {
		t.Due = q.Due
	}
	if q.Note != "" {
		t.Notes = q.Note
	}
	return t
}

// ApplyQueryAttributes merges the query's operators into a task.
func (t *Task) ApplyQueryAttributes(q *Query) {
	applyOperators(t, q)
	if !q.Due.IsZero() {
		t.Due = q.Due
	}
	if q.Text != "" {
		t.Summary = q.Text
	}
	if q.Note != "" {
		appendNote(t, q.Note)
	}
}

func nextFreeId(ts Tasks, m IdsMap) int {
	used := map[int]bool{}
	for _, t := range ts {
		if t.Status == Resolved {
			continue
		}
		if id, ok := m[t.UUID]; ok {
			used[id] = true
		}
	}
	for i := 1; ; i++ {
		if !used[i] {
			return i
		}
	}
}

// saveIds assigns and persists ids for all tasks plus a new one.
func saveIds(env *Env, ts Tasks, newUUID string) int {
	ids := AssignIds(ts, env.ids)
	id := nextFreeId(ts, ids)
	if newUUID != "" {
		ids[newUUID] = id
	}
	if err := SaveIds(env.repo, ids); err != nil {
		errorf("Failed to save ids")
		os.Exit(1)
	}
	env.ids = ids
	return id
}

// cmdAdd implements the add command.
func cmdAdd(env *Env, ts Tasks, q *Query) {
	if q.Text == "" && !q.Template {
		fail("task description or template required")
	}
	t := newTaskFromQuery(q)
	if len(q.IDs) > 0 {
		for _, src := range ts {
			if src.id == q.IDs[0] {
				if t.Summary == "" {
					t.Summary = src.Summary
				}
				if len(q.Tags) == 0 {
					t.Tags = append([]string{}, src.Tags...)
				}
				if q.Project == "" {
					t.Project = src.Project
				}
				if q.Priority == "" {
					t.Priority = src.Priority
				}
				if q.Due.IsZero() {
					t.Due = src.Due
				}
				if t.Notes == "" {
					t.Notes = src.Notes
				}
				t.DelegatedTo = src.DelegatedTo
				t.SubTasks = append([]SubTask{}, src.SubTasks...)
				t.Dependencies = append([]string{}, src.Dependencies...)
				break
			}
		}
	}
	if t.Summary == "" {
		fail("task description or template required")
	}
	sortStrings(t.Tags)
	if err := Save(env.repo, t); err != nil {
		errorf("Failed to create directory in git repository")
		os.Exit(1)
	}
	id := saveIds(env, ts, t.UUID)
	t.id = id
	fmt.Printf("\nAdded %d: %s\n", id, t.Summary)
	env.git.Commit(fmt.Sprintf("Added %d: %s", id, t.Summary))
}

// cmdLog implements the log command (add an already resolved task).
func cmdLog(env *Env, ts Tasks, q *Query) {
	if q.Text == "" {
		fail("task description required")
	}
	t := newTaskFromQuery(q)
	t.Status = Resolved
	t.Resolved = time.Now().UTC()
	if err := Save(env.repo, t); err != nil {
		errorf("Failed to create directory in git repository")
		os.Exit(1)
	}
	fmt.Printf("\nLogged %s\n", t.Summary)
	env.git.Commit(fmt.Sprintf("Logged %s", t.Summary))
}

// cmdTemplate implements the template command.
func cmdTemplate(env *Env, ts Tasks, q *Query) {
	var t Task
	if len(q.IDs) > 0 {
		found := false
		for _, src := range ts {
			if src.id == q.IDs[0] {
				t = src
				found = true
				break
			}
		}
		if !found {
			fail("no open task with ID %d exists", q.IDs[0])
		}
		t.UUID = NewUUID()
		t.Status = Template
		t.Created = time.Now().UTC()
		t.Resolved = time.Time{}
		if q.Text != "" {
			t.Summary = q.Text
		}
		if q.Note != "" {
			appendNotePadded(&t, q.Note)
		}
		applyOperators(&t, q)
		if !q.Due.IsZero() {
			t.Due = q.Due
		}
	} else {
		if q.Text == "" {
			fail("task description or template required")
		}
		t = newTaskFromQuery(q)
		t.Status = Template
	}
	if err := Save(env.repo, t); err != nil {
		errorf("Failed to create directory in git repository")
		os.Exit(1)
	}
	id := saveIds(env, ts, t.UUID)
	t.id = id
	fmt.Printf("\nCreated Template %d: %s\n", id, t.Summary)
	env.git.Commit(fmt.Sprintf("Created Template %d: %s", id, t.Summary))
}

// resolveTasks returns the tasks addressed by the query.
func resolveTasks(ts Tasks, q *Query) Tasks {
	if len(q.IDs) > 0 {
		var out Tasks
		for _, id := range q.IDs {
			for _, t := range ts {
				if t.id == id {
					out = append(out, t)
					break
				}
			}
		}
		return out
	}
	var out Tasks
	for _, t := range ts {
		if q.Matches(t) {
			out = append(out, t)
		}
	}
	return out
}

// allOpenTasks returns the tasks matching the query, applying the context.
func allOpenTasks(ts Tasks, q *Query) Tasks {
	var out Tasks
	for _, t := range ts {
		if q.Matches(t) {
			out = append(out, t)
		}
	}
	return out
}

// cmdStart implements the start command.
func cmdStart(env *Env, ts Tasks, q *Query) {
	targets := resolveTasks(ts, q)
	if len(targets) == 0 {
		fail("no open task with ID %d exists", firstId(q))
	}
	for _, t := range targets {
		if t.Status == Active {
			errorf("invalid state transition: %s -> active", t.Status)
			os.Exit(1)
		}
		nt := t
		nt.Status = Active
		if q.Note != "" {
			appendNotePadded(&nt, q.Note)
		}
		if err := Save(env.repo, nt); err != nil {
			errorf("Failed to save task")
			os.Exit(1)
		}
		fmt.Printf("\nStarted %d: %s\n", nt.id, nt.Summary)
		env.git.Commit(fmt.Sprintf("Started %d: %s", nt.id, nt.Summary))
	}
}

func firstId(q *Query) int {
	if len(q.IDs) > 0 {
		return q.IDs[0]
	}
	return 0
}

// cmdStop implements the stop command.
func cmdStop(env *Env, ts Tasks, q *Query) {
	targets := resolveTasks(ts, q)
	if len(targets) == 0 {
		fail("no open task with ID %d exists", firstId(q))
	}
	for _, t := range targets {
		if t.Status != Active {
			errorf("invalid state transition: %s -> paused", t.Status)
			os.Exit(1)
		}
		nt := t
		nt.Status = Paused
		if q.Note != "" {
			appendNotePadded(&nt, q.Note)
		}
		if err := Save(env.repo, nt); err != nil {
			errorf("Failed to save task")
			os.Exit(1)
		}
		fmt.Printf("\nStopped %d: %s\n", nt.id, nt.Summary)
		env.git.Commit(fmt.Sprintf("Stopped %d: %s", nt.id, nt.Summary))
	}
}

// cmdDone implements the done command.
func cmdDone(env *Env, ts Tasks, q *Query) {
	targets := resolveTasks(ts, q)
	if len(targets) == 0 {
		fail("no open task with ID %d exists", firstId(q))
	}
	for _, t := range targets {
		nt := t
		nt.Status = Resolved
		nt.Resolved = time.Now().UTC()
		if q.Note != "" {
			appendNotePadded(&nt, q.Note)
		}
		if err := Save(env.repo, nt); err != nil {
			errorf("Failed to save task")
			os.Exit(1)
		}
		delete(env.ids, nt.UUID)
		if err := SaveIds(env.repo, env.ids); err != nil {
			errorf("Failed to save ids")
			os.Exit(1)
		}
		fmt.Printf("\nResolved %d: %s\n", nt.id, nt.Summary)
		env.git.Commit(fmt.Sprintf("Resolved %d: %s", nt.id, nt.Summary))
	}
}

// cmdRemove implements the remove command.
func cmdRemove(env *Env, ts Tasks, q *Query) {
	if len(q.IDs) == 0 {
		fail("no ID(s) specified")
	}
	targets := resolveTasks(ts, q)
	if len(targets) == 0 {
		fail("no open task with ID %d exists", q.IDs[0])
	}
	for _, t := range targets {
		fmt.Printf("%s\n", taskString(t))
	}
	for _, t := range targets {
		if err := Remove(env.repo, t); err != nil {
			errorf("Failed to remove task")
			os.Exit(1)
		}
		delete(env.ids, t.UUID)
		if err := SaveIds(env.repo, env.ids); err != nil {
			errorf("Failed to save ids")
			os.Exit(1)
		}
		fmt.Printf("\nRemoved: %s\n", taskString(t))
		env.git.Commit(fmt.Sprintf("Removed: %s", taskString(t)))
	}
}

// cmdModify implements the modify command.
func cmdModify(env *Env, ts Tasks, q *Query) {
	var targets Tasks
	if len(q.IDs) > 0 {
		targets = resolveTasks(ts, q)
		if len(targets) == 0 {
			fail("no open task with ID %d exists", q.IDs[0])
		}
	} else {
		targets = allOpenTasks(ts, q)
		if len(targets) == 0 {
			fail("no tasks in current context or filter")
		}
		if isTTY(os.Stdin) {
			if !ConfirmOrAbort("no IDs specified. Apply to all %d tasks in current ctx?", len(targets)) {
				os.Exit(1)
			}
		}
	}
	for _, t := range targets {
		nt := t
		if !applyOperators(&nt, q) {
			fmt.Printf("\nModified %d: %s\n", nt.id, nt.Summary)
			fmt.Print("\x1b[38;5;245m")
			fmt.Print("No changes detected\n")
			fmt.Print("\x1b[0m")
			continue
		}
		if err := Save(env.repo, nt); err != nil {
			errorf("Failed to save task")
			os.Exit(1)
		}
		fmt.Printf("\nModified %d: %s\n", nt.id, nt.Summary)
		env.git.Commit(fmt.Sprintf("Modified %d: %s", nt.id, nt.Summary))
	}
}
