// applyOperators mutates a task according to the operators in q.
func applyOperators(t *Task, q *Query) bool {
	changed := false
	for _, tag := range q.Tags {
		if !t.HasTag(tag) {
			t.Tags = append(t.Tags, tag)
			sortStrings(t.Tags)
			changed = true
		}
	}
	for _, tag := range q.AntiTags {
		if t.HasTag(tag) {
			t.Tags = removeString(t.Tags, tag)
			changed = true
		}
	}
	if q.Project != "" && t.Project != q.Project {
		t.Project = q.Project
		changed = true
	}
	for _, p := range q.AntiProjects {
		if t.Project == p {
			t.Project = ""
			changed = true
		}
	}
	if q.Priority != "" && string(t.Priority) != q.Priority {
		t.Priority = Priority(q.Priority)
		changed = true
	}
	return changed
}

// Commit stages all changes and commits them with the given message.  When
// nothing has changed, "No changes detected" is printed instead.
func (g *Git) Commit(msg string) {
	fmt.Print("\x1b[38;5;245m")
	cmd := exec.Command(g.bin, "-C", g.repo, "add", ".")
	cmd.Stdout = nil
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		errorf("error: failed to add changes to repo: %v", err)
		os.Exit(1)
	}
	if HasObjects(g.repo) {
		c := exec.Command(g.bin, "-C", g.repo, "diff-index", "--quiet", "HEAD", "--")
		c.Stdout = nil
		c.Stderr = os.Stderr
		if err := c.Run(); err == nil {
			fmt.Print("No changes detected\n")
			fmt.Print("\x1b[0m")
			return
		}
	}
	c := exec.Command(g.bin, "-C", g.repo, "commit", "--no-gpg-sign", "-m", msg)
	c.Stdout = os.Stdout
	c.Stderr = os.Stderr
	if err := c.Run(); err != nil {
		errorf("error: failed to commit changes: %v", err)
		os.Exit(1)
	}
	fmt.Print("\x1b[0m")
}

// ---------- task creation ----------------------------------------------------

func newTaskFromQuery(q *Query) Task {
	t := Task{
		UUID:     NewUUID(),
		Status:   Pending,
		Summary:  q.Text,
		Priority: P2,
		Created:  time.Now().UTC(),
	}
	for _, tag := range q.Tags {
