// resolveTasks returns the tasks addressed by the query.
func resolveTasks(ts Tasks, q *Query) Tasks {
	if len(q.IDs) > 0 {
		var out Tasks
		for _, id := range q.IDs {
			for _, t := range ts {
				if t.id == id {
					out = append(out, t)
					break
				}
			}
		}
		return out
	}
	var out Tasks
	for _, t := range ts {
		if q.Matches(t) {
			out = append(out, t)
		}
	}
	return out
}

