// cmdNote implements the note command.  It requires a terminal.
func cmdNote(env *Env, ts Tasks, q *Query) {
	if !isTTY(os.Stdin) {
		return
	}
	targets := resolveTasks(ts, q)
	if len(targets) == 0 {
		fail("no open task with ID %d exists", firstId(q))
	}
	for _, t := range targets {
		nt := t
		if q.Note != "" {
			appendNote(&nt, q.Note)
		} else {
			text, err := editTempFile("md", nt.id, nt.Summary, nt.Notes)
			if err != nil {
				fail("Failed to run $EDITOR")
			}
			if text == nt.Notes {
				fmt.Printf("\nEdit note %d: %s\n", nt.id, nt.Summary)
				fmt.Print("\x1b[38;5;245mNo changes detected\n\x1b[0m")
				continue
			}
			nt.Notes = text
		}
		if err := Save(env.repo, nt); err != nil {
			errorf("Failed to save task")
			os.Exit(1)
		}
		fmt.Printf("\nEdit note %d: %s\n", nt.id, nt.Summary)
		env.git.Commit(fmt.Sprintf("Edit note %d: %s", nt.id, nt.Summary))
	}
}

// editTempFile creates a temp file, runs $EDITOR on it and returns the result.
func editTempFile(ext string, id int, summary, content string) (string, error) {
	editor := os.Getenv("EDITOR")
	if editor == "" {
		return "", fmt.Errorf("EDITOR not set")
	}
	parts := strings.Fields(editor)
	tmp, err := os.CreateTemp("/tmp", fmt.Sprintf("dstask.%d.%d-%s.%s", randUint32(), id, slug(summary), ext))
	if err != nil {
		return "", err
	}
	name := tmp.Name()
	if _, err := tmp.WriteString(content); err != nil {
		tmp.Close()
		return "", err
	}
	tmp.Close()
	defer os.Remove(name)
	cmd := exec.Command(parts[0], append(parts[1:], name)...)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		return "", err
	}
	data, err := os.ReadFile(name)
	if err != nil {
		return "", err
	}
	return string(data), nil
}

// cmdEdit implements the edit command.
func cmdEdit(env *Env, ts Tasks, q *Query) {
	if len(q.IDs) == 0 {
		fail("no ID(s) specified")
	}
	targets := resolveTasks(ts, q)
	if len(targets) == 0 {
		fail("no open task with ID %d exists", q.IDs[0])
	}
	for _, t := range targets {
		nt := t
		text, err := editTempFile("yml", nt.id, nt.Summary, encodeTask(nt, true))
		if err != nil {
			fail("Failed to run $EDITOR")
		}
		edited, perr := taskFromYaml(text)
		if perr != nil {
			// ask the user whether to try again
			if isTTY(os.Stdin) {
				errorf("Failed to unmarshal yaml: %v", perr)
				fmt.Print("Try again? ")
				if !Confirm("") {
					fail("Aborted.")
				}
				continue
			}
			panic(perr)
		}
		if edited.Status == "" || edited.Status != nt.Status {
			if !validStatus(edited.Status) {
				fail("invalid status specified on task, task %s", nt.UUID)
			}
		}
		for _, d := range edited.Dependencies {
			if !uuidRe.MatchString(d) {
				fail("invalid dependency UUID4, task %s", nt.UUID)
			}
		}
		if edited == nt {
			fmt.Printf("\nEdited %d: %s\n", nt.id, nt.Summary)
			fmt.Print("\x1b[38;5;245mNo changes detected\n\x1b[0m")
			continue
		}
		if edited.Status != nt.Status {
			Remove(env.repo, nt)
		}
		edited.UUID = nt.UUID
		if err := Save(env.repo, edited); err != nil {
			errorf("Failed to save task")
			os.Exit(1)
		}
		fmt.Printf("\nEdited %d: %s\n", nt.id, edited.Summary)
		env.git.Commit(fmt.Sprintf("Edited %d: %s", nt.id, edited.Summary))
	}
}

func validStatus(s Status) bool {
	switch s {
	case Pending, Active, Paused, Resolved, Template, Delegated, Deferred, Recurring:
		return true
	}
	return false
}

// cmdContext implements the context command.
func cmdContext(env *Env, ts Tasks, q *Query) {
	if len(env.args) == 0 {
		fmt.Println(contextString(env.ctx))
		return
