var urlRe = regexp.MustCompile(`(?i)(?:(?:[a-z][a-z0-9+.-]*):\/\/)\S*|(?:www\.)?[a-zA-Z0-9-]+(?:\.[a-zA-Z0-9-]+)*\.(?:TLD)(?:[:\/]\S*)?`)

func findURLs(s string) []string {
	var out []string
	for _, m := range urlRe.FindAllString(s, -1) {
		m = strings.TrimRight(m, ".")
		if m != "" {
			out = append(out, m)
		}
	}
	return out
}

// cmdUndo implements the undo command.
func cmdUndo(env *Env, ts Tasks, q *Query) {
	n := 1
	if len(env.args) > 0 {
		v, err := strconv.Atoi(env.args[0])
		if err != nil {
			helpPrint("undo")
			return
		}
		n = v
	}
	env.git.Undo(n)
}

// cmdSync implements the sync command.
func cmdSync(env *Env, ts Tasks, q *Query) {
	env.git.Sync()
}

// cmdGit implements the git passthrough.
func cmdGit(env *Env, ts Tasks, q *Query) {
	if err := env.git.Passthrough(env.args...); err != nil {
		os.Exit(1)
	}
}

// cmdShowTasks implements the show-* listing commands.
func cmdShowTasks(env *Env, ts Tasks, q *Query, filter func(Task) bool) {
	var out Tasks
	for _, t := range ts {
		if filter(t) && q.Matches(t) {
			out = append(out, t)
		}
	}
	if len(ts) == 0 {
		fmt.Println("No tasks found. Run `dstask help` for instructions.")
		return
	}
	if len(out) == 0 {
		errorf("No matching tasks in given context or filter.")
		return
	}
	out = SortTasks(out)
	out.WithIds(env.ids)
	displayTasks(out, env)
}

// displayTasks renders tasks either as a table (when a terminal is attached)
// or as json.
func displayTasks(ts Tasks, env *Env) {
	if isTTY(os.Stdout) || os.Getenv("DSTASK_FAKE_PTY") != "" {
		if len(ts) == 1 {
			printDetail(ts[0])
			return
		}
		printList(ts)
		return
	}
	printJSON(ts)
}

func printList(ts Tasks) {
	t := NewTable([]string{"ID", "Priority", "Tags", "Due", "Project", "Summary"})
	for _, task := range ts {
		t.AddRow([]string{
			strconv.Itoa(task.id),
			string(task.Priority),
			tagsForDisplay(task),
			dueForDisplay(task),
			task.Project,
			summaryForDisplay(task),
		})
	}
	t.Render(termWidth(), true, taskRowColours(ts))
	fmt.Printf("\n%d tasks.\n", len(ts))
}

func printDetail(t Task) {
	rows := [][2]string{
		{"ID", strconv.Itoa(t.id)},
		{"Priority", string(t.Priority)},
		{"Summary", t.Summary},
		{"Status", string(t.Status)},
		{"Project", t.Project},
		{"Tags", tagsForDetail(t)},
		{"UUID", t.UUID},
		{"Created", timeForDetail(t.Created)},
	}
	if !t.Due.IsZero() {
		rows = append(rows, [2]string{"Due", timeForDetail(t.Due)})
	}
	DetailTable(rows, termWidth()).Render(termWidth(), false, detailColours(len(rows)))
	if strings.TrimSpace(t.Notes) != "" {
		fmt.Printf("\nNotes on task %d:\n", t.id)
		fmt.Printf("\x1b[38;5;245m%s\x1b[0m\n", t.Notes)
		fmt.Print("\n")
	}
}

func detailColours(n int) []string {
	out := make([]string, n)
	for i := range out {
		bg := bgNormal
		if i%2 != 0 {
			bg = bgStriped
		}
		out[i] = fmt.Sprintf("\x1b[0;38;5;250;48;5;%dm", bg)
	}
	return out
}
