package main

import (
	"fmt"
	"os"
	"syscall"
	"unsafe"
)

// Env carries everything a command needs.
type Env struct {
	repo string
	git  *Git
	ts   Tasks
	ids  IdsMap
	ctx  *Query
	args []string
}

func main() {
	args := os.Args[1:]
	// Commands that work without a repository.
	if len(args) > 0 {
		switch args[0] {
		case "version":
			printVersion()
			return
		case "help":
			printHelp(args[1:])
			return
		case "bash-completion", "zsh-completion", "fish-completion":
			printCompletion(args[0])
			return
		}
	}
	q, perr := ParseQuery(args, nil)
	if perr != nil {
		fail("%v", perr)
	}
	env, err := setup(q)
	if err != nil {
		fail("%v", err)
	}
	dispatch(env, q)
}

// setup prepares the repository and loads all state.
func setup(q *Query) (*Env, error) {
	repo := RepoDir()
	if _, err := os.Stat(repo); os.IsNotExist(err) {
		g, err := NewGit(repo)
		if err != nil {
			return nil, err
		}
		if err := InitRepo(repo); err != nil {
			return nil, err
		}
		_ = g
	}
	g, err := NewGit(repo)
	if err != nil {
		return nil, err
	}
	ts, err := Load(repo)
	if err != nil {
		return nil, err
	}
	ids := LoadIds(repo)
	ts = ts.WithIds(ids)
	st := LoadState(repo)
	env := &Env{repo: repo, git: g, ts: ts, ids: ids, ctx: nil}
	if st != nil {
		env.ctx = st.Context
	}
	env.args = env.args
	return env, nil
}

func dispatch(env *Env, q *Query) {
	// apply context unless ignored
	eff := q
	if q.IgnoreContext {
		eff = &Query{Cmd: q.Cmd, IDs: q.IDs, Text: q.Text, Note: q.Note, Due: q.Due, Template: q.Template}
	} else if env.ctx != nil {
		eff = &Query{Cmd: q.Cmd, IDs: q.IDs, Text: q.Text, Note: q.Note, Due: q.Due, Template: q.Template}
		eff.Tags = append(append([]string{}, env.ctx.Tags...), q.Tags...)
		eff.AntiTags = append(append([]string{}, env.ctx.AntiTags...), q.AntiTags...)
		eff.Project = env.ctx.Project
		if q.Project != "" {
			eff.Project = q.Project
		}
		eff.AntiProjects = env.ctx.AntiProjects
		eff.Priority = env.ctx.Priority
		if q.Priority != "" {
			eff.Priority = q.Priority
		}
	}
	ts := env.ts
	switch q.Cmd {
	case "", "next":
		showTasks(env, ts, eff, func(t Task) bool { return t.Status != Resolved }, false)
	case "add":
		cmdAdd(env, ts, eff)
	case "log":
		cmdLog(env, ts, eff)
	case "template":
		cmdTemplate(env, ts, eff)
	case "start":
		cmdStart(env, ts, eff)
	case "stop":
		cmdStop(env, ts, eff)
	case "done":
		cmdDone(env, ts, eff)
	case "remove":
		cmdRemove(env, ts, eff)
	case "modify":
		cmdModify(env, ts, eff)
	case "edit":
		cmdEdit(env, ts, eff)
	case "note":
		cmdNote(env, ts, eff)
	case "context":
		cmdContext(env, ts, q)
	case "open":
		cmdOpen(env, ts, eff)
	case "undo":
		cmdUndo(env, ts, q)
	case "sync":
		cmdSync(env, ts, q)
	case "git":
		cmdGit(env, ts, q)
	case "show-open":
		showTasks(env, ts, eff, func(t Task) bool { return t.Status != Resolved }, false)
	case "show-active":
		showTasks(env, ts, eff, func(t Task) bool { return t.Status == Active }, false)
	case "show-paused":
		showTasks(env, ts, eff, func(t Task) bool { return t.Status == Paused }, false)
	case "show-templates":
		showTasks(env, ts, eff, func(t Task) bool { return t.Status == Template }, false)
	case "show-unorganised":
		showTasks(env, ts, eff, func(t Task) bool {
			return t.Status != Resolved && len(t.Tags) == 0 && t.Project == ""
		}, false)
	case "show-resolved":
		showTasks(env, ts, eff, func(t Task) bool { return t.Status == Resolved }, true)
	case "show-projects":
		showProjects(env, ts)
	case "show-tags":
		showTags(env, ts, eff)
	case "_completions":
		cmdCompletions(env, ts, q)
	default:
		// unknown command: treat as a filter on the open tasks
		showTasks(env, ts, eff, func(t Task) bool { return t.Status != Resolved }, false)
	}
}

// showTasks filters and displays tasks.
func showTasks(env *Env, ts Tasks, q *Query, filter func(Task) bool, jsonOnly bool) {
	var out Tasks
	for _, t := range ts {
		if filter(t) && q.Matches(t) {
			out = append(out, t)
		}
	}
	if len(ts) == 0 {
		fmt.Println("No tasks found. Run `dstask help` for instructions.")
		return
	}
	if len(out) == 0 {
		errorf("No matching tasks in given context or filter.")
		return
	}
	out = SortTasks(out)
	out.WithIds(env.ids)
	if jsonOnly {
		printJSON(out)
		return
	}
	displayTasks(out, env)
}

func termWidth() int {
	if os.Getenv("DSTASK_FAKE_PTY") != "" {
		return 80
	}
	if !isTTY(os.Stdout) {
		return 80
	}
	var sz struct {
		rows uint16
		cols uint16
		x    uint16
		y    uint16
	}
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, os.Stdout.Fd(),
		uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&sz)))
	if errno != 0 {
		return 0
	}
	return int(sz.cols)
}
