		showTasks(env, ts, eff, func(t Task) bool { return t.Status == Paused }, false)
	case "show-templates":
		showTasks(env, ts, eff, func(t Task) bool { return t.Status == Template }, false)
	case "show-unorganised":
		showTasks(env, ts, eff, func(t Task) bool {
			return t.Status != Resolved && len(t.Tags) == 0 && t.Project == ""
		}, false)
	case "show-resolved":
		showTasks(env, ts, eff, func(t Task) bool { return t.Status == Resolved }, true)
	case "show-projects":
		showProjects(env, ts)
	case "show-tags":
		showTags(env, ts, eff)
	case "_completions":
		cmdCompletions(env, ts, q)
	default:
		// unknown command: treat as a filter on the open tasks
		showTasks(env, ts, eff, func(t Task) bool { return t.Status != Resolved }, false)
	}
}

// showTasks filters and displays tasks.
func showTasks(env *Env, ts Tasks, q *Query, filter func(Task) bool, jsonOnly bool) {
	var out Tasks
	for _, t := range ts {
		if filter(t) && q.Matches(t) {
			out = append(out, t)
		}
	}
	if len(ts) == 0 {
		fmt.Println("No tasks found. Run `dstask help` for instructions.")
		return
	}
	if len(out) == 0 {
		errorf("No matching tasks in given context or filter.")
		return
	}
	out = SortTasks(out)
	out.WithIds(env.ids)
	if jsonOnly {
		printJSON(out)
		return
	}
	displayTasks(out, env)
}

func termWidth() int {
	if os.Getenv("DSTASK_FAKE_PTY") != "" {
		return 80
	}
	if !isTTY(os.Stdout) {
		return 80
	}
	var sz struct {
		rows uint16
		cols uint16
		x    uint16
		y    uint16
	}
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, os.Stdout.Fd(),
		uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&sz)))
	if errno != 0 {
		return 0
	}
	return int(sz.cols)
}
