package main

import (
	"fmt"
	"math/rand"
	"os"
	"sort"
	"strconv"
)

func randUint32() uint32 { return rand.Uint32() }

// cmdCompletions implements the hidden _completions command used by the shell
// completion scripts.
func cmdCompletions(env *Env, ts Tasks, q *Query) {
	args := env.args
	word := ""
	if len(args) > 0 {
		word = args[len(args)-1]
	}
	// determine the command context: the first argument that names a command
	cmd := ""
	for _, a := range args {
		if isCommand(a) {
			cmd = a
			break
		}
	}
	// candidates
	var cands []string
	cands = append(cands, allCommandWords...)
	cands = append(cands, "P0", "P1", "P2", "P3")
	// filter tasks using the current context and any filter words
	eff := q
	if env.ctx != nil {
		eff.Tags = append(append([]string{}, env.ctx.Tags...), q.Tags...)
		eff.AntiTags = append(append([]string{}, env.ctx.AntiTags...), q.AntiTags...)
		eff.Project = env.ctx.Project
		eff.AntiProjects = env.ctx.AntiProjects
		eff.Priority = env.ctx.Priority
	}
	var filtered Tasks
	for _, t := range ts {
		if eff.Matches(t) {
			filtered = append(filtered, t)
		}
	}
	// projects
	pset := map[string]bool{}
	var projects []string
	for _, t := range filtered {
		if t.Project != "" && !pset[t.Project] {
			pset[t.Project] = true
			projects = append(projects, t.Project)
		}
	}
	sort.Strings(projects)
	for _, p := range projects {
		cands = append(cands, "project:"+p, "-project:"+p)
	}
	// tags: map iteration order (as the original does)
	tagSet := map[string]bool{}
	var tags []string
	for _, t := range filtered {
		for _, tg := range t.Tags {
			if !tagSet[tg] {
				tagSet[tg] = true
				tags = append(tags, tg)
			}
		}
	}
	for _, tg := range tags {
		cands = append(cands, "+"+tg, "-"+tg)
	}
	_ = cmd
	out := []string{}
	for _, c := range cands {
		if c != word && hasPrefix(c, word) {
			out = append(out, c)
		}
	}
	for _, o := range out {
		fmt.Println(o)
	}
}

func hasPrefix(s, p string) bool {
	return len(s) >= len(p) && s[:len(p)] == p
}

// applyContextEnv handles the DSTASK_CONTEXT environment override.
func applyContextEnv(env *Env) {
	v := os.Getenv("DSTASK_CONTEXT")
	if v == "" {
		return
	}
	q, err := ParseQuery(splitFields(v), nil)
	if err != nil {
		return
	}
	q.Cmd = ""
	q.IDs = nil
	env.ctx = q
}

func splitFields(s string) []string {
	var out []string
	cur := ""
	for _, r := range s {
		if r == ' ' || r == '\t' || r == '\n' {
			if cur != "" {
				out = append(out, cur)
				cur = ""
			}
			continue
		}
		cur += string(r)
	}
	if cur != "" {
		out = append(out, cur)
	}
	return out
}

var _ = strconv.Itoa
